<#
.SYNOPSIS
  Permanent Fit Launcher auto-install repair/bootstrapper.

.DESCRIPTION
  Reinstalls the proven FitLauncher Path Bridge + AutoInstall Guardian stack that fixes the
  Fit Launcher UUID-job-folder vs title-named-download-folder failure. The installed bridge
  keeps installation automation flags enabled and makes Fit Launcher's expected
  <job_path>\setup.exe valid as soon as a download is complete (or via safe active-download
  junction/proxy fallback when possible), so Fit Launcher can launch setup immediately.

  Proven failure it fixes:
    Fit Launcher logs StartInstall for F:\Downloads\<uuid>\setup.exe, while the real
    completed game folder is title-named and contains setup.exe elsewhere.

  Default run is safe and non-destructive: no reboot, no game deletion, no app uninstall.
  Existing bridge/guardian/proxy files are timestamp-backed-up before replacement.

.PARAMETER VerifyOnly
  Do not install. Parse/self-test the embedded bridge payload and inspect live Fit Launcher state.

.PARAMETER SelfTestOnly
  Do not install. Write payloads to a temp folder and run the bridge synthetic canary test.

.PARAMETER NoStart
  Install/repair files and tasks but do not start tasks immediately.

.PARAMETER ReportPath
  Optional explicit JSON report path.

.EXAMPLE
  powershell.exe -NoProfile -ExecutionPolicy Bypass -File .\FitLauncher_AutoInstall_Permanent_Repair.ps1

.EXAMPLE
  powershell.exe -NoProfile -ExecutionPolicy Bypass -File .\FitLauncher_AutoInstall_Permanent_Repair.ps1 -VerifyOnly
#>
[CmdletBinding()]
param(
  [switch]$VerifyOnly,
  [switch]$SelfTestOnly,
  [switch]$NoStart,
  [string]$ReportPath
)

$ErrorActionPreference = 'Stop'
Set-StrictMode -Version 2.0

$BridgePayloadBase64 = @'

'@
$GuardianPayloadBase64 = @'

'@
$ProxyPayloadBase64 = @'

'@
$PayloadHashes = @{
  Bridge   = '60FFC6A4170A72EA4B655CA79F91F01987A52BACFBFAF5ADE8762224AF223194'
  Guardian = '9BC83856B8BC1B2F650373FF414FD4E8BE6E41D763C9649ED8DE0958B3150A4C'
  Proxy    = '5363B0088009D7C8554AABDD36D775A59B77DB3F7E9222A34E1B5E7DAD44DE82'
}

function New-Dir { param([string]$Path) if(-not (Test-Path -LiteralPath $Path -PathType Container)){ New-Item -ItemType Directory -Force -Path $Path | Out-Null } }
function Read-TextShared {
  param([Parameter(Mandatory=$true)][string]$Path)
  if(-not (Test-Path -LiteralPath $Path -PathType Leaf)){ return $null }
  $fs=$null; $sr=$null
  try {
    $fs=[System.IO.File]::Open($Path,[System.IO.FileMode]::Open,[System.IO.FileAccess]::Read,[System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete)
    $sr=New-Object System.IO.StreamReader($fs,[System.Text.Encoding]::UTF8,$true)
    return $sr.ReadToEnd()
  } finally { if($sr){$sr.Dispose()} elseif($fs){$fs.Dispose()} }
}
function Save-Bytes { param([string]$Path,[byte[]]$Bytes) New-Dir (Split-Path -Parent $Path); [System.IO.File]::WriteAllBytes($Path,$Bytes) }
function Get-HashText { param([string]$Path) if(Test-Path -LiteralPath $Path -PathType Leaf){ return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash } return $null }
function Backup-IfExists {
  param([string]$Path,[string]$BackupDir)
  if(Test-Path -LiteralPath $Path -PathType Leaf){
    New-Dir $BackupDir
    $stamp=Get-Date -Format 'yyyyMMdd_HHmmss'
    $dest=Join-Path $BackupDir ((Split-Path -Leaf $Path) + '.' + $stamp + '.bak')
    Copy-Item -LiteralPath $Path -Destination $dest -Force
    return $dest
  }
  return $null
}
function Assert-Hash {
  param([string]$Path,[string]$Expected)
  if([string]::IsNullOrWhiteSpace($Expected)){ return }
  $actual=Get-HashText $Path
  if($actual -ne $Expected){ throw "Hash mismatch for $Path expected=$Expected actual=$actual" }
}
function Test-PowerShellParse {
  param([Parameter(Mandatory=$true)][string]$Path)
  $tokens=$null; $errors=$null
  [void][System.Management.Automation.Language.Parser]::ParseFile($Path,[ref]$tokens,[ref]$errors)
  if($errors -and $errors.Count -gt 0){
    $msg = ($errors | ForEach-Object { $_.Message + ' at line ' + $_.Extent.StartLineNumber }) -join '; '
    throw "PowerShell parser failed for $Path :: $msg"
  }
  return $true
}
function Get-FitRoot { Join-Path $env:APPDATA 'com.fitlauncher.carrotrub' }
function Get-Paths {
  $root=Get-FitRoot
  [pscustomobject]@{
    Root=$root
    Scripts=Join-Path $root 'scripts'
    Logs=Join-Path $root 'logs'
    Bridge=Join-Path $root 'scripts\FitLauncherPathBridge.ps1'
    Guardian=Join-Path $root 'scripts\FitLauncherAutoInstallGuardian.ps1'
    Proxy=Join-Path $root 'scripts\FitLauncherSetupProxy.exe'
    Manager=Join-Path $root 'manager.json'
    Config=Join-Path $root 'config.json'
    InstallConfig=Join-Path $root 'fitgirlConfig\settings\installation\installation.json'
    BridgeLog=Join-Path $root 'logs\path-bridge.log'
    GuardianLog=Join-Path $root 'logs\auto-install-guardian.log'
    BackupDir=Join-Path $root ('scripts\backups\permanent-repair-' + (Get-Date -Format 'yyyyMMdd_HHmmss'))
  }
}
function ConvertFrom-JsonSafe { param([string]$Raw) if([string]::IsNullOrWhiteSpace($Raw)){ return $null } return ($Raw | ConvertFrom-Json) }
function Save-JsonFile {
  param([string]$Path,$Object)
  New-Dir (Split-Path -Parent $Path)
  $tmp=$Path + '.tmp_' + ([guid]::NewGuid().ToString('N'))
  Set-Content -LiteralPath $tmp -Value ($Object | ConvertTo-Json -Depth 64) -Encoding UTF8
  Move-Item -LiteralPath $tmp -Destination $Path -Force
}
function Ensure-InstallFlags {
  param([string]$InstallConfig)
  New-Dir (Split-Path -Parent $InstallConfig)
  $cfg=ConvertFrom-JsonSafe (Read-TextShared -Path $InstallConfig)
  if($null -eq $cfg){ $cfg = New-Object psobject }
  $changed=$false
  foreach($prop in @('auto_clean','auto_install','two_gb_limit','directx_install','microsoftcpp_install')){
    if($cfg.PSObject.Properties.Name -notcontains $prop){ Add-Member -InputObject $cfg -MemberType NoteProperty -Name $prop -Value $true; $changed=$true }
    elseif($cfg.$prop -ne $true){ $cfg.$prop=$true; $changed=$true }
  }
  if($changed){ Save-JsonFile -Path $InstallConfig -Object $cfg }
  return $cfg
}
function Write-Payloads {
  param($Paths,[string]$BackupDir)
  $bridgeBytes=[Convert]::FromBase64String(($BridgePayloadBase64 -replace '\s',''))
  $guardianBytes=[Convert]::FromBase64String(($GuardianPayloadBase64 -replace '\s',''))
  $proxyBytes = if([string]::IsNullOrWhiteSpace($ProxyPayloadBase64)){ [byte[]]@() } else { [Convert]::FromBase64String(($ProxyPayloadBase64 -replace '\s','')) }
  Backup-IfExists -Path $Paths.Bridge -BackupDir $BackupDir | Out-Null
  Backup-IfExists -Path $Paths.Guardian -BackupDir $BackupDir | Out-Null
  Backup-IfExists -Path $Paths.Proxy -BackupDir $BackupDir | Out-Null
  Save-Bytes -Path $Paths.Bridge -Bytes $bridgeBytes
  Save-Bytes -Path $Paths.Guardian -Bytes $guardianBytes
  if($proxyBytes.Length -gt 0){ Save-Bytes -Path $Paths.Proxy -Bytes $proxyBytes }
  Assert-Hash -Path $Paths.Bridge -Expected $PayloadHashes.Bridge
  Assert-Hash -Path $Paths.Guardian -Expected $PayloadHashes.Guardian
  if($proxyBytes.Length -gt 0){ Assert-Hash -Path $Paths.Proxy -Expected $PayloadHashes.Proxy }
  Test-PowerShellParse -Path $Paths.Bridge | Out-Null
  Test-PowerShellParse -Path $Paths.Guardian | Out-Null
}
function Invoke-BridgeSelfTest {
  param([string]$BridgePath)
  Test-PowerShellParse -Path $BridgePath | Out-Null
  $psExe = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
  & $psExe -NoProfile -ExecutionPolicy Bypass -File $BridgePath -SelfTest
  $exit = $LASTEXITCODE
  if($exit -ne 0){ throw "Bridge self-test failed exit=$exit" }
  return 'SELFTEST_OK child_exit_0'
}
function Register-FitLauncherTasks {
  param($Paths)
  $psExe = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
  $user = [System.Security.Principal.WindowsIdentity]::GetCurrent().Name
  $principal = New-ScheduledTaskPrincipal -UserId $user -LogonType Interactive -RunLevel Limited
  $bridgeAction = New-ScheduledTaskAction -Execute $psExe -Argument ('-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File "' + $Paths.Bridge + '"')
  $guardianAction = New-ScheduledTaskAction -Execute $psExe -Argument ('-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File "' + $Paths.Guardian + '"')
  $bridgeTrigger = New-ScheduledTaskTrigger -AtLogOn -User $user
  $guardianLogon = New-ScheduledTaskTrigger -AtLogOn -User $user
  $guardianMinute = New-ScheduledTaskTrigger -Once -At (Get-Date).AddMinutes(1)
  $guardianMinute.Repetition.Interval = 'PT1M'
  $guardianMinute.Repetition.Duration = 'P3650D'
  $bridgeSettings = New-ScheduledTaskSettingsSet -MultipleInstances IgnoreNew -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -RestartCount 999 -RestartInterval (New-TimeSpan -Minutes 1) -ExecutionTimeLimit (New-TimeSpan -Days 365)
  $guardianSettings = New-ScheduledTaskSettingsSet -MultipleInstances IgnoreNew -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -RestartCount 3 -RestartInterval (New-TimeSpan -Minutes 1) -ExecutionTimeLimit (New-TimeSpan -Minutes 5)
  Register-ScheduledTask -TaskName 'FitLauncher Path Bridge' -Action $bridgeAction -Trigger $bridgeTrigger -Principal $principal -Settings $bridgeSettings -Description 'Keeps Fit Launcher auto-install job paths aligned with completed downloads.' -Force | Out-Null
  Register-ScheduledTask -TaskName 'FitLauncher AutoInstall Guardian' -Action $guardianAction -Trigger @($guardianLogon,$guardianMinute) -Principal $principal -Settings $guardianSettings -Description 'Keeps Fit Launcher auto-install flags enabled and bridge running.' -Force | Out-Null
}
function Start-RepairedTasks {
  try { Stop-ScheduledTask -TaskName 'FitLauncher Path Bridge' -ErrorAction SilentlyContinue } catch {}
  Start-Sleep -Milliseconds 500
  Start-ScheduledTask -TaskName 'FitLauncher AutoInstall Guardian'
  Start-ScheduledTask -TaskName 'FitLauncher Path Bridge'
}
function Inspect-State {
  param($Paths)
  $tasks=@()
  foreach($name in @('FitLauncher Path Bridge','FitLauncher AutoInstall Guardian')){
    $t=Get-ScheduledTask -TaskName $name -ErrorAction SilentlyContinue
    if($t){
      $i=$t | Get-ScheduledTaskInfo
      $tasks += [pscustomobject]@{Name=$name;State=(''+$t.State);Enabled=[bool]$t.Settings.Enabled;LastTaskResult=$i.LastTaskResult;LastRunTime=$i.LastRunTime;NextRunTime=$i.NextRunTime}
    } else { $tasks += [pscustomobject]@{Name=$name;Missing=$true} }
  }
  $procs = @(Get-CimInstance Win32_Process -Filter "name='powershell.exe'" -ErrorAction SilentlyContinue | Where-Object { $_.CommandLine -like '*FitLauncherPathBridge.ps1*' } | Select-Object ProcessId,CommandLine)
  $installFlags = ConvertFrom-JsonSafe (Read-TextShared -Path $Paths.InstallConfig)
  $bridgeTail = if(Test-Path -LiteralPath $Paths.BridgeLog){ Get-Content -LiteralPath $Paths.BridgeLog -Tail 12 -ErrorAction SilentlyContinue } else { @() }
  $guardianTail = if(Test-Path -LiteralPath $Paths.GuardianLog){ Get-Content -LiteralPath $Paths.GuardianLog -Tail 12 -ErrorAction SilentlyContinue } else { @() }
  [pscustomobject]@{
    Time=(Get-Date).ToString('o')
    FitRoot=$Paths.Root
    BridgeHash=Get-HashText $Paths.Bridge
    GuardianHash=Get-HashText $Paths.Guardian
    ProxyHash=Get-HashText $Paths.Proxy
    InstallFlags=$installFlags
    Tasks=$tasks
    BridgeProcesses=$procs
    RecentBridgeLog=$bridgeTail
    RecentGuardianLog=$guardianTail
  }
}

$paths=Get-Paths
New-Dir $paths.Scripts; New-Dir $paths.Logs
if([string]::IsNullOrWhiteSpace($ReportPath)){ $ReportPath = Join-Path $paths.Logs ('permanent-repair-report-' + (Get-Date -Format 'yyyyMMdd_HHmmss') + '.json') }

try {
  if($SelfTestOnly -or $VerifyOnly){
    $tmp = Join-Path $env:TEMP ('FitLauncherPermanentRepairVerify_' + [guid]::NewGuid().ToString('N'))
    New-Dir $tmp
    $tmpBridge=Join-Path $tmp 'FitLauncherPathBridge.ps1'
    $tmpGuardian=Join-Path $tmp 'FitLauncherAutoInstallGuardian.ps1'
    Save-Bytes -Path $tmpBridge -Bytes ([Convert]::FromBase64String(($BridgePayloadBase64 -replace '\s','')))
    Save-Bytes -Path $tmpGuardian -Bytes ([Convert]::FromBase64String(($GuardianPayloadBase64 -replace '\s','')))
    Test-PowerShellParse -Path $tmpBridge | Out-Null
    Test-PowerShellParse -Path $tmpGuardian | Out-Null
    $self = Invoke-BridgeSelfTest -BridgePath $tmpBridge
    $state = if($VerifyOnly){ Inspect-State -Paths $paths } else { [pscustomobject]@{Skipped='SelfTestOnly does not touch live Fit Launcher state'} }
    $report=[pscustomobject]@{Mode=if($SelfTestOnly){'SelfTestOnly'}else{'VerifyOnly'};PayloadHashes=$PayloadHashes;SelfTest=$self;State=$state;Result='VERIFY_OK'}
    $report | ConvertTo-Json -Depth 32 | Set-Content -LiteralPath $ReportPath -Encoding UTF8
    Write-Host "VERIFY_OK report=$ReportPath"
    exit 0
  }

  Write-Payloads -Paths $paths -BackupDir $paths.BackupDir
  $flags = Ensure-InstallFlags -InstallConfig $paths.InstallConfig
  Register-FitLauncherTasks -Paths $paths
  $selfTest = Invoke-BridgeSelfTest -BridgePath $paths.Bridge
  if(-not $NoStart){ Start-RepairedTasks }
  Start-Sleep -Seconds 3
  # Run guardian one-shot too, so flags/tasks are repaired even before the next minute tick.
  & (Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe') -NoProfile -ExecutionPolicy Bypass -File $paths.Guardian | Out-Null
  Start-Sleep -Seconds 2
  $state = Inspect-State -Paths $paths
  $report=[pscustomobject]@{
    Result='INSTALLED_OK'
    Meaning='Fit Launcher auto-install bridge and guardian are installed, parsed, self-tested, scheduled, and started.'
    PayloadHashes=$PayloadHashes
    SelfTest=$selfTest
    BackupDir=$paths.BackupDir
    State=$state
  }
  $report | ConvertTo-Json -Depth 64 | Set-Content -LiteralPath $ReportPath -Encoding UTF8
  Write-Host "INSTALLED_OK report=$ReportPath"
  Write-Host "BridgeHash=$($state.BridgeHash) GuardianHash=$($state.GuardianHash) ProxyHash=$($state.ProxyHash)"
  exit 0
} catch {
  $err = $_.Exception.Message
  $fail=[pscustomobject]@{Result='FAILED';Error=$err;Script=$PSCommandPath;Time=(Get-Date).ToString('o')}
  try { $fail | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $ReportPath -Encoding UTF8 } catch {}
  Write-Error $err
  exit 1
}
